#include <bits/stdc++.h>
using namespace std;

vector<int> stockSpans(vector<int>& prices) {
    vector<int> spans;
    stack<pair<int, int>> st;  // {price, day}
    for (int day = 0; day < (int)prices.size(); ++day) {
        while (!st.empty() && st.top().first <= prices[day]) st.pop();
        int span = st.empty() ? day + 1 : day - st.top().second;
        st.push({prices[day], day});
        spans.push_back(span);
    }
    return spans;
}

