import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public int[] stockSpans(int[] prices) {
        int n = prices.length;
        int[] spans = new int[n];
        Deque<long[]> stack = new ArrayDeque<>();  // {price, day}
        for (int day = 0; day < n; ++day) {
            while (!stack.isEmpty() && stack.peek()[0] <= prices[day]) stack.pop();
            spans[day] = stack.isEmpty() ? day + 1 : (int)(day - stack.peek()[1]);
            stack.push(new long[]{prices[day], day});
        }
        return spans;
    }
}
